CREATE TABLE public.restaurants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, logo_url text, background_url text, description text, delivery_time text NOT NULL DEFAULT '25-35 min', rating numeric NOT NULL DEFAULT 4.5 CHECK (rating BETWEEN 1 AND 5), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.restaurants TO anon, authenticated; GRANT ALL ON public.restaurants TO service_role;
ALTER TABLE public.restaurants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Active restaurants are public" ON public.restaurants FOR SELECT TO anon, authenticated USING (is_active);
CREATE TABLE public.menu_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, name text NOT NULL, sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,name), UNIQUE(id,restaurant_id));
GRANT SELECT ON public.menu_categories TO anon, authenticated; GRANT ALL ON public.menu_categories TO service_role;
ALTER TABLE public.menu_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Active restaurant categories are public" ON public.menu_categories FOR SELECT TO anon, authenticated USING (EXISTS(SELECT 1 FROM public.restaurants r WHERE r.id=restaurant_id AND r.is_active));
CREATE TABLE public.menu_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, category_id uuid NOT NULL, name text NOT NULL, description text, price numeric NOT NULL DEFAULT 0 CHECK(price>=0), image_url text, is_available boolean NOT NULL DEFAULT true, is_featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(category_id,restaurant_id) REFERENCES public.menu_categories(id,restaurant_id) ON DELETE CASCADE);
GRANT SELECT ON public.menu_items TO anon, authenticated; GRANT ALL ON public.menu_items TO service_role;
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Available restaurant items are public" ON public.menu_items FOR SELECT TO anon, authenticated USING (is_available AND EXISTS(SELECT 1 FROM public.restaurants r WHERE r.id=restaurant_id AND r.is_active));
CREATE TABLE public.ads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, image_url text, category text NOT NULL CHECK(category IN ('restaurant','grocery','send_package','receive_package','paxi')), target_type text, target_id text, target_url text NOT NULL, cta_text text NOT NULL DEFAULT 'Order Now', is_active boolean NOT NULL DEFAULT true, priority int NOT NULL DEFAULT 0, clicks int NOT NULL DEFAULT 0, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ads TO anon, authenticated; GRANT ALL ON public.ads TO service_role;
ALTER TABLE public.ads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Active promotions are public" ON public.ads FOR SELECT TO anon, authenticated USING(is_active);
CREATE OR REPLACE FUNCTION public.record_ad_click(ad_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.ads SET clicks=clicks+1 WHERE id=ad_id AND is_active; $$;
REVOKE ALL ON FUNCTION public.record_ad_click(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_ad_click(uuid) TO anon, authenticated;
CREATE INDEX menu_items_restaurant_category ON public.menu_items(restaurant_id,category_id);
CREATE INDEX ads_active_priority ON public.ads(is_active,priority);
COMMENT ON TABLE public.restaurant_menus IS 'DEPRECATED: replaced by restaurant-scoped menu_items; retained for additive migration and legacy imports.';